mapper.select:
select o.orgname as UnitDeptidName,g.orgname as CreateDeptidName,a.ORGNAME as CreateUnitidName ,s.REALNAME as CreateStaffidName,k.risknumber as risknumber,r.* from TBL_RISK_MONTHLY_EVALUATION r left join TBL_ORGANIZATION o on r.UNIT_DEPTID=o.ORGID left join TBL_ORGANIZATION g on r.CREATE_DEPTID=g.ORGID left join TBL_ORGANIZATION a on r.CREATE_UNITID=a.ORGID left join TBL_STAFF s on r.CREATE_STAFFID=s.STAFFID left join tbl_risk k on k.riskid=r.riskid where 1=1 and r.status=6
and id in
#{item}
and a.orgname LIKE concat(concat('%',#{queryParam.createUnitidName} ),'%')
and o.orgname LIKE concat(concat('%',#{queryParam.unitDeptidName} ),'%')
and year(r.create_Time)=#{queryParam.year}
and r.ONE_RISK LIKE concat(concat('%',#{queryParam.oneRisk} ),'%')
and r.TWO_RISK LIKE concat(concat('%',#{queryParam.twoRisk} ),'%')
and r.THREE_RISK LIKE concat(concat('%',#{queryParam.threeRisk} ),'%')
and k.risknumber LIKE concat(concat('%',#{queryParam.risknumber} ),'%')
and r.month >= #{queryParam.monthL}
and r.month <= #{queryParam.monthR}
${sql} order by id desc

select distinct s.*,O.ORGNAME AS unitname from TBL_RISK_ASSPLAN_RISK r left join TBL_RISK_RISKMARKING a on a.assriskid=r.assriskid left join TBL_RISK_ASSPLAN p on p.assplanid=r.assplanid left join TBL_RISK s on s.riskid=r.riskid left join TBL_ORGANIZATION O ON O.ORGID=S.UNIT where r.assdate=(SELECT MAX(ASSDATE) FROM TBL_RISK_ASSPLAN_RISK WHERE RISKID = s.riskid)
and s.risknumber LIKE concat(concat('%',#{queryParam.risknumber} ),'%')
and s.riskname LIKE concat(concat('%',#{queryParam.riskname} ),'%')
and s.belongsto =#{queryParam.belongsto}
and O.orgname like concat(concat('%',#{queryParam.unitname} ),'%')
and s.belongsto =#{queryParam.belongsto}
and p.unit=#{company}
and s.riskid in
#{item}
and a.asssatus=2 ${sql} order by s.riskcreatedt desc

select o.orgname as UnitDeptidName,g.orgname as CreateDeptidName,a.ORGNAME as CreateUnitidName ,s.REALNAME as CreateStaffidName,k.risknumber as risknumber,r.* from TBL_RISK_MONTHLY_EVALUATION r left join TBL_ORGANIZATION o on r.UNIT_DEPTID=o.ORGID left join TBL_ORGANIZATION g on r.CREATE_DEPTID=g.ORGID left join TBL_ORGANIZATION a on r.CREATE_UNITID=a.ORGID left join TBL_STAFF s on r.CREATE_STAFFID=s.STAFFID left join tbl_risk k on k.riskid=r.riskid where 1=1 and r.riskid is not null
and r.riskid=#{queryParam.riskid}
${sql} order by id desc

select o.orgname as UnitDeptidName,g.orgname as CreateDeptidName,a.ORGNAME as CreateUnitidName ,s.REALNAME as CreateStaffidName,k.risknumber as risknumber,r.* from TBL_RISK_MONTHLY_EVALUATION r left join TBL_ORGANIZATION o on r.UNIT_DEPTID=o.ORGID left join TBL_ORGANIZATION g on r.CREATE_DEPTID=g.ORGID left join TBL_ORGANIZATION a on r.CREATE_UNITID=a.ORGID left join TBL_STAFF s on r.CREATE_STAFFID=s.STAFFID left join tbl_risk k on k.riskid=r.riskid where 1=1 and r.riskid is not null
and r.riskid=#{riskid}
and id in
#{item}
${sql} order by id desc
